import { Component } from '@angular/core';
import { CommonModule } from '@angular/common';

@Component({
  selector: 'app-gallery',
  standalone: true,
  imports: [CommonModule],
  template: `
    <section class="gallery">
      <div class="container">
        <h2>Galeria</h2>

        <div class="gallery-grid">
          <div *ngFor="let photo of photos" class="gallery-item">
            <img [src]="photo" alt="Zdjęcie">
          </div>
        </div>

        <p class="placeholder-text" *ngIf="photos.length === 0">
          Wrzuć zdjęcia do folderu /assets/images/gallery/
        </p>
      </div>
    </section>
  `,
  styles: [`
    .gallery {
      padding: 5rem 0;
      background: white;
    }

    .container {
      max-width: 1200px;
      margin: 0 auto;
      padding: 0 2rem;
    }

    h2 {
      font-family: 'Playfair Display', serif;
      font-size: 3rem;
      text-align: center;
      margin-bottom: 3rem;
      color: #333;
    }

    .gallery-grid {
      display: grid;
      grid-template-columns: repeat(auto-fill, minmax(250px, 1fr));
      gap: 1rem;
    }

    .gallery-item {
      aspect-ratio: 1;
      overflow: hidden;
      border-radius: 8px;
    }

    .gallery-item img {
      width: 100%;
      height: 100%;
      object-fit: cover;
      transition: transform 0.3s;
    }

    .gallery-item img:hover {
      transform: scale(1.1);
    }

    .placeholder-text {
      text-align: center;
      font-family: 'Lato', sans-serif;
      color: #999;
      font-style: italic;
    }
  `]
})
export class GalleryComponent {
  // Dodaj ścieżki do swoich zdjęć tutaj
  photos: string[] = [
    // '/assets/images/gallery/photo1.jpg',
    // '/assets/images/gallery/photo2.jpg',
    // itd.
  ];
}
